// 参考解答：原木切割（二分答案）
// "长度 L 可行" 指所有原木按 L 切出的段数总和 >= k。可行性随 L 增大单调变差，
// 因此可以对 L 二分：可行就记录并尝试更长（lo=mid+1），不可行就缩短（hi=mid-1）。
// 两个溢出陷阱：k 可达 10^10（必须 long long 读入）；段数总和可达 3×10^9（必须 long long 累加）。
#include <iostream>
using namespace std;

int n;
long long k;
int L[3005];

// 当每段长度为 len 时，能切出的总段数（用 long long 求和防溢出）
long long countPieces(int len) {
    long long c = 0;
    for (int i = 0; i < n; i++) c += L[i] / len;   // 每根原木贡献 L[i]/len 段，余料丢弃
    return c;
}

int main() {
    cin >> n >> k;
    int maxL = 0;
    for (int i = 0; i < n; i++) { cin >> L[i]; if (L[i] > maxL) maxL = L[i]; }
    int lo = 1, hi = maxL, ans = 0;
    while (lo <= hi) {
        int mid = lo + (hi - lo) / 2;
        if (countPieces(mid) >= k) { ans = mid; lo = mid + 1; }  // 可行：尝试更长的 L
        else hi = mid - 1;                                       // 不可行：必须缩短
    }
    cout << ans << "\n";   // ans 保持 0 表示连 L=1 都凑不够 k 段
    return 0;
}

// 参考解答：网格路径计数（带障碍，递推 DP）
// dp[i][j] = 从 (1,1) 走到 (i,j) 的路径数。只能向右/向下，所以
// dp[i][j] = dp[i-1][j] + dp[i][j-1]（障碍格 dp=0）。
// 起点或终点是障碍时直接输出 0。
#include <iostream>
using namespace std;

int grid[16][16];
long long dp[16][16];   // 用 long long 稳妥存储（题目保证答案在 int 范围内）

int main() {
    int N, M;
    cin >> N >> M;
    for (int i = 1; i <= N; i++)
        for (int j = 1; j <= M; j++)
            cin >> grid[i][j];
    if (grid[1][1] == 1 || grid[N][M] == 1) { cout << 0 << "\n"; return 0; }
    dp[1][1] = 1;
    for (int i = 1; i <= N; i++)
        for (int j = 1; j <= M; j++) {
            if (i == 1 && j == 1) continue;
            if (grid[i][j] == 1) { dp[i][j] = 0; continue; }        // 障碍格不可达
            dp[i][j] = dp[i-1][j] + dp[i][j-1];                      // 全局数组越界行为 0，首行首列自然正确
        }
    cout << dp[N][M] << "\n";
    return 0;
}

